// Valida o JSON do medidor e calcula as métricas de entrega (evidências de teste)
const p = msg.payload;
if (typeof p !== 'object' || p === null) {
    msg.erro = 'payload não é JSON';
    return [null, msg];
}
const obrigatorios = ['codigo', 'seq', 'potencia_w', 'kwh', 'custo_estimado',
                      'meta_mensal_reais', 'percentual_meta', 'faixa'];
const faltando = obrigatorios.filter(c => p[c] === undefined || p[c] === null);
if (faltando.length) {
    msg.erro = 'campos ausentes: ' + faltando.join(', ');
    return [null, msg];
}
if (p.potencia_w < 0 || p.kwh < 0 || !['VERDE', 'AMARELO', 'VERMELHO'].includes(p.faixa)) {
    msg.erro = 'valores fora do esperado';
    return [null, msg];
}

// ---- Métricas por medidor ----
const todas = flow.get('metricas') || {};
let m = todas[p.codigo];
// seq = 1 sem ser reenvio = medidor reiniciou: recomeça a contagem
if (!m || (p.seq === 1 && !p.reenvio)) {
    m = { recebidas: 0, unicas: 0, duplicadas: 0, reenvios: 0, maiorSeq: 0,
          vistos: {}, somaAtrasoAoVivo: 0, qtdAoVivo: 0, maiorAtrasoReenvio: 0 };
}
m.recebidas++;
msg.duplicada = !!m.vistos[p.seq];
if (msg.duplicada) {
    m.duplicadas++;
} else {
    m.vistos[p.seq] = true;
    m.unicas++;
}
if (p.reenvio) m.reenvios++;
if (p.seq > m.maiorSeq) m.maiorSeq = p.seq;

// Atraso = hora de chegada - hora da leitura (o relógio do ESP32 vem do NTP)
let atraso = null;
if (p.dt_leitura) {
    atraso = Math.max(0, (Date.now() - Date.parse(p.dt_leitura)) / 1000);
    if (p.reenvio) {
        m.maiorAtrasoReenvio = Math.max(m.maiorAtrasoReenvio, atraso);
    } else {
        m.somaAtrasoAoVivo += atraso;
        m.qtdAoVivo++;
    }
}

const perdidas = Math.max(0, m.maiorSeq - m.unicas);
todas[p.codigo] = m;
flow.set('metricas', todas);

msg.metricas = {
    recebidas: m.recebidas,
    perdidas: perdidas,
    duplicadas: m.duplicadas,
    reenvios: m.reenvios,
    taxaEntrega: m.maiorSeq ? (100 * m.unicas / m.maiorSeq).toFixed(1) : '100.0',
    atrasoMedioAoVivo: m.qtdAoVivo ? (m.somaAtrasoAoVivo / m.qtdAoVivo).toFixed(1) : '-',
    maiorAtrasoReenvio: m.maiorAtrasoReenvio.toFixed(0)
};
msg.atraso_s = atraso;
node.status({ fill: 'green', shape: 'dot',
              text: `#${p.seq} ${p.faixa} · entrega ${msg.metricas.taxaEntrega}%` });
return [msg, null];

const p = msg.payload;
const m = msg.metricas;
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const cor = { VERDE: '#2e7d32', AMARELO: '#f9a825', VERMELHO: '#c62828' }[p.faixa];
return [
    { payload: Number(p.percentual_meta) },
    p.reenvio ? null : { topic: 'Potência (W)', payload: Number(p.potencia_w) },
    { payload: `${brl(p.custo_estimado)} de ${brl(p.meta_mensal_reais)}` },
    { payload: `<b style="color:${cor}">${p.faixa}</b>` },
    { payload: brl(p.projecao_mes) + (p.alerta_projecao ? ' ⚠ vai passar da meta' : '') },
    { payload: `dia ${p.dia_ciclo}/30 · ${Number(p.kwh).toFixed(2).replace('.', ',')} kWh` },
    { payload: `${m.recebidas} recebidas · ${m.perdidas} perdidas · ${m.reenvios} reenviadas` },
    { payload: `${m.taxaEntrega}% · atraso médio ${m.atrasoMedioAoVivo} s` },
    { payload: `${p.buffer_pendente} no buffer · maior atraso de reenvio ${m.maiorAtrasoReenvio} s` }
];

// Ponte para a API Java: agrega as leituras de 5 s em 1 leitura por minuto.
// O medidor manda o kWh ACUMULADO do mês, mas a API soma o kWh de cada leitura
// no resumo mensal. Então enviamos só o que foi consumido na janela (delta).
const JANELA_MS = 60 * 1000;
const p = msg.payload;
if (msg.duplicada) return null;              // mesma seq já contada

const kwh = Number(p.kwh);
const instante = p.dt_leitura ? Date.parse(p.dt_leitura) : Date.now();
const estados = flow.get('apiJanelas') || {};
let j = estados[p.codigo];

if (!j) {
    // 1ª leitura desde que o Node-RED subiu: vira a base (não reenvia o mês inteiro)
    estados[p.codigo] = { kwhBase: kwh, inicio: instante, somaPot: 0, n: 0 };
    flow.set('apiJanelas', estados);
    node.status({ fill: 'grey', shape: 'ring', text: `base ${kwh.toFixed(3)} kWh` });
    return null;
}
if (kwh < j.kwhBase) j.kwhBase = 0;          // medidor reiniciou ou zerou o ciclo

j.somaPot += Number(p.potencia_w);
j.n++;
j.ultimoDt = p.dt_leitura || null;
if (instante - j.inicio < JANELA_MS) { flow.set('apiJanelas', estados); return null; }

const delta = Number((kwh - j.kwhBase).toFixed(6));
const potMedia = j.somaPot / j.n;
const dt = j.ultimoDt;
j.inicio = instante; j.somaPot = 0; j.n = 0;
if (delta <= 0) {                            // sem consumo: fica para a próxima janela
    flow.set('apiJanelas', estados);
    node.status({ fill: 'grey', shape: 'ring', text: 'janela sem consumo' });
    return null;
}
j.kwhBase = kwh;
flow.set('apiJanelas', estados);

const leitura = {
    potenciaW: Number(potMedia.toFixed(3)),
    kwh: delta
};
// "2026-11-13T10:00:00-03:00" -> "2026-11-13T10:00:00" (a API usa LocalDateTime no fuso de SP)
if (dt) leitura.dataLeitura = dt.substring(0, 19);

node.status({ fill: 'blue', shape: 'dot', text: `${delta} kWh · ${leitura.potenciaW} W` });
return {
    leitura: {
        codigo: p.codigo,
        corpo: leitura,
        // usados só se o dispositivo ainda não existir na conta
        dispositivo: { codigo: p.codigo, tarifaKwh: Number(p.tarifa_kwh),
                       metaMensalReais: Number(p.meta_mensal_reais) }
    }
};

// Uma requisição por vez. A fila guarda as leituras se a API estiver fora do ar
// (mesma ideia do buffer offline do ESP32, agora entre o Node-RED e a API).
const MAX_FILA = 500;
const base = (env.get('API_URL') || '').replace(/\/$/, '');
const fila = flow.get('apiFila') || [];

if (msg.leitura) {
    fila.push(msg.leitura);
    if (fila.length > MAX_FILA) fila.shift();
    flow.set('apiFila', fila);
}
const ocupado = flow.get('apiOcupado') || 0;
if (ocupado && Date.now() - ocupado < 30000) return null;   // já tem requisição em andamento
if (!fila.length) {
    node.status({ fill: 'green', shape: 'dot', text: 'fila vazia' });
    return null;
}
if (!base) {
    node.status({ fill: 'red', shape: 'ring', text: 'defina API_URL' });
    return null;
}

const json = { 'Content-Type': 'application/json', 'Accept': 'application/json' };
const req = (etapa, method, path, payload, token) => {
    flow.set('apiOcupado', Date.now());
    node.status({ fill: 'yellow', shape: 'dot', text: `${etapa} · ${fila.length} na fila` });
    const headers = Object.assign({}, json);
    if (token) headers.Authorization = 'Bearer ' + token;
    return { etapa, method, url: base + path, headers, payload: payload || '' };
};

// 1) Token JWT (vale 2 h; renova 5 min antes)
const auth = flow.get('apiAuth');
if (!auth || auth.expira - Date.now() < 5 * 60 * 1000) {
    const telefone = env.get('API_TELEFONE'), senha = env.get('API_SENHA');
    if (!telefone || !senha) {
        node.status({ fill: 'red', shape: 'ring', text: 'defina API_TELEFONE e API_SENHA' });
        return null;
    }
    return req('login', 'POST', '/api/v1/auth/login', { telefone, senha });
}

// 2) Id numérico do dispositivo (a API usa id na rota; o medidor conhece o código)
const item = fila[0];
const ids = flow.get('apiDispositivos') || {};
if (!(item.codigo in ids)) return req('listar', 'GET', '/api/v1/dispositivos', null, auth.token);
if (ids[item.codigo] === null) return req('criar', 'POST', '/api/v1/dispositivos', item.dispositivo, auth.token);

// 3) A leitura em si
return req('leitura', 'POST', `/api/v1/dispositivos/${ids[item.codigo]}/leituras`, item.corpo, auth.token);

// Decide o que fazer com cada resposta e, se deu certo, pede a próxima requisição.
flow.set('apiOcupado', 0);
const fila = flow.get('apiFila') || [];
const ids = flow.get('apiDispositivos') || {};
const s = msg.statusCode;
const p = msg.payload;
const continuar = { topic: 'continuar' };
const log = (texto) => ({ payload: `${msg.etapa} ${s}: ${texto}` });

// Sem resposta (API desligada, rede): espera o próximo tique de 30 s
if (typeof s !== 'number') {
    node.status({ fill: 'red', shape: 'ring', text: `API fora do ar (${s}) · ${fila.length} na fila` });
    return [null, log('sem conexão, tento de novo em 30 s')];
}
if (s === 401 && msg.etapa !== 'login') {          // token vencido ou API reiniciada
    flow.set('apiAuth', null);
    return [continuar, log('token recusado, fazendo login de novo')];
}

switch (msg.etapa) {
case 'login':
    if (s === 200 && p && p.token) {
        flow.set('apiAuth', { token: p.token, expira: Date.parse(p.expiraEm) });
        return [continuar, log('login ok')];
    }
    node.status({ fill: 'red', shape: 'ring', text: 'login recusado: confira API_TELEFONE/API_SENHA' });
    return [null, log('login recusado')];

case 'listar':
    if (s === 200 && Array.isArray(p)) {
        const codigo = fila[0] && fila[0].codigo;
        p.forEach(d => { ids[d.codigo] = d.id; });
        if (codigo && !(codigo in ids)) ids[codigo] = null;   // não existe: será criado
        flow.set('apiDispositivos', ids);
        return [continuar, log(`${p.length} dispositivo(s) na conta`)];
    }
    break;

case 'criar':
    if (s === 201 && p && p.id) {
        ids[p.codigo] = p.id;
        flow.set('apiDispositivos', ids);
        return [continuar, log(`dispositivo ${p.codigo} criado com id ${p.id}`)];
    }
    if (s === 409) {                                 // código já pertence a outra conta
        const codigo = fila[0].codigo;
        flow.set('apiFila', fila.filter(i => i.codigo !== codigo));
        delete ids[codigo];
        flow.set('apiDispositivos', ids);
        node.status({ fill: 'red', shape: 'ring', text: `${codigo} pertence a outra conta` });
        return [null, log(`${codigo} já está cadastrado em outra conta; leituras descartadas`)];
    }
    break;

case 'leitura':
    if (s === 201) {
        fila.shift();
        flow.set('apiFila', fila);
        node.status({ fill: 'green', shape: 'dot',
                      text: `leitura ${p.id} · R$ ${p.custoEstimado} · ${fila.length} na fila` });
        return [continuar, log(`leitura ${p.id} gravada: ${p.kwh} kWh, R$ ${p.custoEstimado}`)];
    }
    if (s === 404) {                                 // dispositivo apagado na API: descobre de novo
        delete ids[fila[0].codigo];
        flow.set('apiDispositivos', ids);
        return [continuar, log('dispositivo não encontrado, procurando de novo')];
    }
    if (s === 400) {                                 // leitura recusada: não adianta repetir
        const ruim = fila.shift();
        flow.set('apiFila', fila);
        node.warn({ recusada: ruim, resposta: p });
        return [continuar, log('leitura recusada pela validação da API')];
    }
    break;
}
// Outros erros (500, 503...): mantém na fila e tenta no próximo tique
node.status({ fill: 'red', shape: 'ring', text: `erro ${s} em ${msg.etapa} · ${fila.length} na fila` });
return [null, log('erro, tento de novo em 30 s')];

// Uma linha por leitura em /data/leituras.csv (base das métricas do README)
const p = msg.payload;
const linhas = [];
if (!context.get('cabecalho')) {
    linhas.push('recebido_em;codigo;seq;dt_leitura;irms_a;potencia_w;kwh;custo_estimado;' +
                'percentual_meta;faixa;projecao_mes;buffer_pendente;reenvio;atraso_s');
    context.set('cabecalho', true);
}
linhas.push([new Date().toISOString(), p.codigo, p.seq, p.dt_leitura || '', p.irms_a, p.potencia_w,
             p.kwh, p.custo_estimado, p.percentual_meta, p.faixa, p.projecao_mes,
             p.buffer_pendente, p.reenvio, msg.atraso_s === null ? '' : msg.atraso_s.toFixed(1)].join(';'));
return { payload: linhas.join('\n') };

// Mudança de faixa -> aviso em linguagem simples (o mesmo texto iria para o WhatsApp/app)
const p = msg.payload;
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const dicas = {
    VERDE: 'Seu consumo voltou ao normal. Continue assim!',
    AMARELO: 'Atenção: já usou ' + Math.round(p.percentual_meta) + '% da meta. Que tal encurtar o banho e tirar aparelhos da tomada?',
    VERMELHO: 'A conta de luz passou da meta! Veja no app onde dá para economizar.'
};
msg.payload = `Energia ${p.faixa_anterior} → ${p.faixa}: ${brl(p.custo_estimado)} de ${brl(p.meta_mensal_reais)}. ${dicas[p.faixa] || ''}`;
msg.topic = 'Grana Amiga';
return msg;

// "online" ao conectar; "offline" publicado pelo broker (Last Will) se o medidor cair
const codigo = msg.topic.split('/')[2];
const online = msg.payload === 'online';
node.status({ fill: online ? 'green' : 'red', shape: 'dot', text: codigo + ' ' + msg.payload });
const texto = { payload: `<b style="color:${online ? '#2e7d32' : '#c62828'}">${codigo} ${online ? 'ONLINE' : 'OFFLINE'}</b>` };
const aviso = online ? null : { topic: 'Grana Amiga', payload: `Medidor ${codigo} sem conexão. As leituras ficam guardadas nele e chegam quando a internet voltar.` };
return [texto, aviso];

const p = msg.payload;
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
msg.topic = 'Fechamento do mês';
msg.payload = `${Number(p.kwh).toFixed(1).replace('.', ',')} kWh · ${brl(p.custo_estimado)} · ` +
              (p.dentro_da_meta ? 'dentro da meta 🎉' : 'acima da meta de ' + brl(p.meta_mensal_reais));
return msg;

// Remove campos vazios e envia para granaamiga/casa/<DISPOSITIVO>/config
const cmd = {};
for (const [k, v] of Object.entries(msg.payload || {})) {
    if (v !== '' && v !== null && v !== undefined) cmd[k] = (k === 'comando') ? v : Number(v);
}
if (!Object.keys(cmd).length) return null;
const codigo = env.get('DISPOSITIVO') || 'GA-ESP32-001';
return { topic: `granaamiga/casa/${codigo}/config`, payload: cmd, qos: 1 };

const p = msg.payload;
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const rej = (p.rejeitados || []).length ? ' · rejeitado: ' + p.rejeitados.join(', ') : '';
return { topic: 'Medidor confirmou', payload: `meta ${brl(p.meta_mensal_reais)} · tarifa R$ ${p.tarifa_kwh}/kWh · ${p.tensao_v} V${rej}` };
